J.Cavalry.loaderSource="/* Loader \u003c-> panel bridge over Cavalry's WebServer / WebClient.\n   Both APIs are documented, but this build was written with Cavalry closed, so every call is guarded and a\n   failure is not fatal: the panel and the loader each build a JSON they were given, on their own. */\nvar JZBridge = (function () {\n'use strict';\nvar PORT = 41234, VERSION = 'JIZURA_CV/1';\n\nfunction hasServer() { return typeof api !== 'undefined' && typeof api.WebServer === 'function'; }\nfunction hasClient() { return typeof api !== 'undefined' && typeof api.WebClient === 'function'; }\n\n/* Panel side: listen for posted assemblies. Returns false when the host has no WebServer. */\nvar bound = null;\nfunction start(onMessage) {\n  if (!hasServer()) return false;\n  if (bound) return true;\n  var server;\n  try {\n    server = new api.WebServer();\n    if (typeof server.setResultForGet === 'function') server.setResultForGet(VERSION);\n    if (typeof server.addCallbackObject === 'function') server.addCallbackObject({\n      onPost: function () {\n        try {\n          var guard = 0;\n          while (typeof server.postCount === 'function' && server.postCount() > 0 && guard++ \u003c 16) {\n            var post = server.getNextPost();\n            var text = post && (post.result != null ? post.result : post.body);\n            if (text == null) continue;\n            var msg = typeof text === 'string' ? JSON.parse(text) : text;\n            if (!msg) continue;\n            var assembly = msg.path ? JSON.parse(api.readFromFile(msg.path)) : msg.assembly;\n            if (assembly) onMessage(assembly, msg);\n          }\n        } catch (e) { console.warn('JIZURA bridge: ' + (e && e.message || e)); }\n      }\n    });\n    if (typeof server.listen === 'function') server.listen('localhost', PORT);\n    if (typeof server.setHighFrequency === 'function') server.setHighFrequency();\n    bound = server;\n    return true;\n  } catch (e) {\n    console.warn('JIZURA bridge: WebServer unavailable (' + (e && e.message || e) + '). Pick the JSON in the panel instead.');\n    return false;\n  }\n}\n\n/* Loader side: send the file path when a panel answers, otherwise return false and let the loader build. */\nfunction handoff(file) {\n  if (!hasClient()) return false;\n  try {\n    var client = new api.WebClient('http://localhost:' + PORT);\n    client.get('/get');\n    if (typeof client.status === 'function' && client.status() !== 200) return false;\n    var body = typeof client.body === 'function' ? String(client.body() || '') : '';\n    if (body.indexOf('JIZURA_CV') !== 0) return false;\n    client.post('/post', JSON.stringify({ type: 'path', path: file }), 'application/json');\n    return typeof client.status !== 'function' || client.status() === 200;\n  } catch (e) {\n    return false;\n  }\n}\n\nreturn { version: VERSION, port: PORT, start: start, handoff: handoff, server: hasServer, client: hasClient };\n})();\n\n/* JIZURA CV Loader. Run from the JavaScript Editor (or keep it in the Scripts folder and run it there).\n   It posts the picked assembly to an open JIZURA CV panel when Cavalry's WebClient can reach it, and builds\n   the composition itself otherwise, so it never depends on the panel being open. */\n(function () {\n  if (typeof ui === 'undefined' || typeof api === 'undefined' || typeof JZCavalry === 'undefined') return;\n\n  function folder() {\n    try { return api.getFolderFromPath(api.getSceneFilePath() || '') || ''; } catch (error) { return ''; }\n  }\n\n  function summary(result, assembly) {\n    var r = result.report || { built: {}, fallback: {}, missing: {}, errors: [] };\n    return '\uc644\ub8cc: \ub808\uc774\uc5b4 ' + result.layerIds.length + ' / \ud14d\uc2a4\ud2b8 ' + (assembly.nodeCount || 0) +\n      ' / \uc815\ud655 ' + Object.keys(r.built).length + ' \u00b7 \uadfc\uc0ac ' + Object.keys(r.fallback).length +\n      ' \u00b7 \ubbf8\uc9c0\uc6d0 ' + Object.keys(r.missing).length + ' \u00b7 \uc624\ub958 ' + r.errors.length;\n  }\n\n  ui.setTitle('JIZURA CV Loader');\n  var status = new ui.Label('JIZURA\uc758 .jizura.cavalry.json\uc744 \uc120\ud0dd\ud558\uba74 \ucef4\ud3ec\uc9c0\uc158\uc744 \uc0dd\uc131\ud569\ub2c8\ub2e4.');\n  var button = new ui.Button('Cavalry JSON \ubd88\ub7ec\uc624\uae30');\n\n  button.onClick = function () {\n    var file = api.presentOpenFile(folder(), 'JIZURA Cavalry JSON', 'JIZURA Assembly (*.json)');\n    if (!file) return;\n\n    if (typeof JZBridge !== 'undefined' && JZBridge.handoff(file)) {\n      status.setText('JIZURA CV \ud328\ub110\ub85c \uc804\uc1a1\ud588\uc2b5\ub2c8\ub2e4. \ud328\ub110 \ucabd \ud654\uba74\uc744 \ud655\uc778\ud574\uc8fc\uc138\uc694.');\n      return;\n    }\n\n    var assembly;\n    try { assembly = JSON.parse(api.readFromFile(file)); }\n    catch (error) { status.setText('\ubd88\ub7ec\uc624\uae30 \uc2e4\ud328: ' + (error && error.message || error)); return; }\n    if (!assembly || assembly.format !== 'jizura.cavalry.assembly') {\n      status.setText('JIZURA\uc758 JSON\uc774 \uc544\ub2d9\ub2c8\ub2e4: ' + file);\n      return;\n    }\n\n    try {\n      var result = JZCavalry.run(assembly, { componentPath: null, fontOverrides: {}, timingPaths: null });\n      status.setText(summary(result, assembly) + ' (\ud328\ub110 \ubbf8\uc5f0\uacb0\ub85c \uc778\ud574 \uc9c1\uc811 \uc0dd\uc131\ud568)');\n      console.log('JIZURA report:\\n' + JSON.stringify(result.report || {}, null, 2));\n    } catch (error) {\n      status.setText('\uc2e4\ud328: ' + (error && error.message || error));\n      console.error('JIZURA: ' + (error && error.stack || error));\n    }\n  };\n\n  ui.add(status);\n  ui.add(button);\n  ui.addStretch();\n  ui.show();\n})();\n";
/* Native recipe registry. No family aliases; no host access at registration time. */
var JZNative = (function () {
'use strict';
var groups = ['layout','enter','hold','exit','decor','treat','bg','cam','fx','trans'];
var recipes = Object.create(null);
groups.forEach(function (g) { recipes[g] = Object.create(null); });
function register(group, name, def) {
  if (!recipes[group] || typeof name !== 'string' || !name || !def || typeof def.build !== 'function') throw new Error('Invalid native recipe: '+group+':'+name);
  if (recipes[group][name]) throw new Error('Duplicate native recipe: '+group+':'+name);
  if (!def.source || !def.scope) throw new Error('Recipe needs source and scope: '+group+':'+name);
  recipes[group][name] = def;
}
function get(group, name) { return recipes[group] && recipes[group][name] || null; }
function manifest() {
  var out = {};
  groups.forEach(function (g) { out[g] = {}; Object.keys(recipes[g]).sort().forEach(function (k) {
    var d = recipes[g][k]; out[g][k] = {source:d.source,scope:d.scope,exact:false,hostVerified:false,differences:d.differences || []};
  }); });
  return out;
}
function finite(v, label) { if (typeof v !== 'number' || !isFinite(v)) throw new Error('Non-finite '+label); return v; }
function clamp(x) { return Math.max(0,Math.min(1,x)); }
function outExpo(x) { x=clamp(x); return x===1?1:1-Math.pow(2,-10*x); }
function hash(a,b,c,d,e) {
  var h=0x9e3779b9^(a|0); h=Math.imul(h^(h>>>16),0x85ebca6b);
  h=(h+Math.imul((b|0)+0x632be5ab,0xc2b2ae35))|0; h=Math.imul(h^(h>>>13),0xc2b2ae35);
  h=(h+Math.imul((c|0)+0x5bd1e995,0x27d4eb2f))|0; h=Math.imul(h^(h>>>15),0x165667b1);
  h=(h+Math.imul((d|0)+0x1b873593,0x85ebca6b))|0; h=Math.imul(h^(h>>>16),0x27d4eb2f);
  h=(h+Math.imul((e|0)+0x68e31da4,0x9e3779b1))|0; h^=h>>>15; h=Math.imul(h,0x2c1b3c6d); h^=h>>>12; h=Math.imul(h,0x297a2d39); h^=h>>>15;
  return h>>>0;
}
return {register:register,get:get,manifest:manifest,groups:groups,finite:finite,clamp:clamp,outExpo:outExpo,
  random:function(a,b,c,d,e){return hash(a,b,c,d,e)/4294967296;}};
})();

