  var W = c.comp.width, Hh = c.comp.height, md = Math.min(W, Hh), d = P.dir < 0 ? -1 : 1;
  var s0 = ((P.s0 || 0) | 0) + 3, y0 = P.y || 0.5, pb = (w.a.sc || c.sc).bg;
  var light = H.lum(c.sc.bg) > 0.6 && H.lum(pb) > 0.6;
